/* ── Slug utility ── */
export function toSlug(name: string): string {
  return name
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

/* ── Types ── */
export type Producto = {
  name: string;
  sub: string;
  desc: string;
  Art: () => React.JSX.Element;
  img?: string;
  images?: string[]; // múltiples fotos para carrusel
  price?: string;    // ej: "$1.200.000", "Desde $900.000", "Consultar precio"
};

export type EstiloData = {
  slug: string;
  label: string;
  tagline: string;
  descripcion: string;
  productos: Producto[];
};

